/**
 * PropertySet carries an optional SHACK attachment (immovable, +rent, one per
 * set). Shack is null when no shack is attached.
 */
export interface PropertySet {
  playerId: string;
  propertySetId: string;
  color: Color;
  cards: Card[];
  shack?: Card | undefined;
}

/**
 * DebtChip is one outstanding debt obligation: DebtorId handed a chip to
 * CreditorId (failed payment or DEBT TRAP) and must settle it with any one
 * hand card at the start of their next turn.
 */
export interface DebtChip {
  id: string;
  debtorId: string;
  creditorId: string;
}

